import java.util.*;
import java.io.*;

/**
 * Variant 5: Using Scanner, with a different matching implementation
 */
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n = sc.nextInt();
        int m = sc.nextInt();
        if (n > m) {
            int tmp = n;
            n = m;
            m = tmp;
        }
        long totalCells = (long) n * m;
        if (totalCells < 100) {
            List<Integer>[] graph = new ArrayList[(int) totalCells];
            for (int i = 0; i < totalCells; i++) {
                graph[i] = new ArrayList<>();
            }
            for (int i = 0; i < totalCells; i++) {
                for (int j = 0; j < totalCells; j++) {
                    int r1 = i / m;
                    int c1 = i % m;
                    int r2 = j / m;
                    int c2 = j % m;
                    if (Math.abs(r1 - r2) + Math.abs(c1 - c2) == 3) {
                        graph[i].add(j);
                    }
                }
            }
            int matchCount = maxMatching(graph);
            pw.println(matchCount * 2);
        } else {
            long res;
            if (n == 1) {
                res = m / 6 * 6 + (m % 6 == 4 ? 2 : 0) + (m % 6 == 5 ? 4 : 0);
            } else {
                res = (long) n * m;
                res -= res % 2;
            }
            pw.println(res);
        }
        pw.close();
        sc.close();
    }

    static int maxMatching(List<Integer>[] g) {
        int n = g.length;
        int[] match = new int[n];
        Arrays.fill(match, -1);
        int result = 0;
        for (int u = 0; u < n; u++) {
            boolean[] visited = new boolean[n];
            if (dfs(g, match, u, visited))
                result++;
        }
        return result;
    }

    static boolean dfs(List<Integer>[] g, int[] match, int u, boolean[] visited) {
        for (int v : g[u]) {
            if (!visited[v]) {
                visited[v] = true;
                if (match[v] == -1 || dfs(g, match, match[v], visited)) {
                    match[v] = u;
                    match[u] = v;
                    return true;
                }
            }
        }
        return false;
    }
}
